-- REVIEW ONLY. Owner approval, verified recovery, maintenance and preflight are required.
-- DDL is not transactionally atomic. Stop on any error; never reset/retry a partial migration.
-- This plan does not create verified balances, grant privileges, update old guards or activate Money Accounts.
-- Execute as the existing upms_guard85@localhost definer after separately verified authority.
DELIMITER $$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_accounts_delete` BEFORE DELETE ON `money_accounts` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_accounts_insert` BEFORE INSERT ON `money_accounts` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_accounts_update` BEFORE UPDATE ON `money_accounts` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_audit_delete` BEFORE DELETE ON `money_audit` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_audit_insert` BEFORE INSERT ON `money_audit` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (NOT EXISTS(SELECT 1 FROM money_batches b WHERE b.id=NEW.batch_id AND b.actor_id=NEW.actor_id AND BINARY b.reason=BINARY NEW.reason AND b.created_at=NEW.created_at)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_audit_update` BEFORE UPDATE ON `money_audit` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_batches_delete` BEFORE DELETE ON `money_batches` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_batches_insert` BEFORE INSERT ON `money_batches` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (CHAR_LENGTH(TRIM(NEW.reason))<3 OR CHAR_LENGTH(TRIM(NEW.source_ref))<1 OR NEW.date>DATE(UTC_TIMESTAMP()+INTERVAL 5 HOUR) OR (NEW.kind<>'OPENING' AND EXISTS(SELECT 1 FROM money_accounts a WHERE a.type='CHEQUE_CUSTODY' AND a.id IN(NEW.from_account_id,NEW.to_account_id))) OR (NEW.kind='REVERSAL' AND NOT EXISTS(SELECT 1 FROM money_batches b WHERE b.id=NEW.corrects_id AND b.kind IN('TRANSFER','SOURCE_CREDIT','SOURCE_DEBIT') AND b.amount=NEW.amount AND (b.from_account_id <=> NEW.to_account_id) AND (b.to_account_id <=> NEW.from_account_id) AND NEW.date>=b.date))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_batches_update` BEFORE UPDATE ON `money_batches` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_movements_delete` BEFORE DELETE ON `money_movements` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_movements_insert` BEFORE INSERT ON `money_movements` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (NOT EXISTS(SELECT 1 FROM money_batches b WHERE b.id=NEW.batch_id AND ((NEW.account_id=b.from_account_id AND NEW.delta=-b.amount) OR (NEW.account_id=b.to_account_id AND NEW.delta=b.amount)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_movements_update` BEFORE UPDATE ON `money_movements` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_schema_receipts_delete` BEFORE DELETE ON `money_schema_receipts` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_schema_receipts_insert` BEFORE INSERT ON `money_schema_receipts` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
CREATE DEFINER=`upms_guard85`@`localhost` TRIGGER `upms32_money_schema_receipts_update` BEFORE UPDATE ON `money_schema_receipts` FOR EACH ROW BEGIN IF SUBSTRING_INDEX(USER(),'@',1)='upms_runtime84' AND (TRUE) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='UPMS_MONEY_PROTECTED'; END IF; END$$
DELIMITER ;
